<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/auth.php';require_roles(['patient_portal']);
$link=$pdo->prepare('SELECT p.* FROM patient_portal_accounts pa JOIN patients p ON p.id=pa.patient_id WHERE pa.user_id=:user_id');$link->execute(['user_id'=>current_user()['id']]);$patient=$link->fetch();if(!$patient){http_response_code(403);exit('Your portal account is not linked to a patient record. Contact hospital reception.');}
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$action=(string)($_POST['action']??'');
 if($action==='book'){
  require_permission('appointments.self_book');$doctor=filter_var($_POST['doctor_id']??'',FILTER_VALIDATE_INT);$when=trim((string)($_POST['scheduled_at']??''));$reason=trim((string)($_POST['reason']??''));$date=DateTime::createFromFormat('!Y-m-d\TH:i',$when);
  if(!$doctor||!$date||$date->format('Y-m-d\TH:i')!==$when||$date<=new DateTime()||strlen($reason)>255){set_flash('danger','Choose a clinician and a future appointment time.');redirect('/hospital%20management/portal/index.php');}
  $check=$pdo->prepare('SELECT d.id FROM doctors d JOIN users u ON u.id=d.user_id WHERE d.id=:id AND u.is_active=1');$check->execute(['id'=>$doctor]);if(!$check->fetch()){set_flash('danger','That clinician is not available.');redirect('/hospital%20management/portal/index.php');}
  $q=$pdo->prepare('INSERT INTO appointments(patient_id,doctor_id,scheduled_at,reason) VALUES(:patient,:doctor,:time,:reason)');$q->execute(['patient'=>$patient['id'],'doctor'=>$doctor,'time'=>$date->format('Y-m-d H:i:s'),'reason'=>$reason?:null]);$id=(string)$pdo->lastInsertId();record_audit('self_book','appointment',$id,'Patient portal appointment request');set_flash('success','Appointment requested. Contact the hospital to confirm availability.');
 }elseif($action==='profile'){
  require_permission('profile.own_update');$phone=trim((string)($_POST['phone']??''));$email=strtolower(trim((string)($_POST['email']??'')));$address=trim((string)($_POST['address']??''));
  if(strlen($phone)>40||($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))||strlen($email)>190||strlen($address)>255){set_flash('danger','Check the phone, email, and address values.');redirect('/hospital%20management/portal/index.php');}
  $q=$pdo->prepare('UPDATE patients SET phone=:phone,email=:email,address=:address WHERE id=:id');$q->execute(['phone'=>$phone?:null,'email'=>$email?:null,'address'=>$address?:null,'id'=>$patient['id']]);record_audit('update','patient',(string)$patient['id'],'Patient updated own portal profile');set_flash('success','Profile updated.');
 }else{http_response_code(400);exit('Unknown portal action.');}
 redirect('/hospital%20management/portal/index.php');
}
$doctors=has_permission('appointments.self_book')?$pdo->query("SELECT d.id,u.full_name FROM doctors d JOIN users u ON u.id=d.user_id WHERE u.is_active=1 ORDER BY u.full_name")->fetchAll():[];
$appointments=[];if(has_permission('appointments.self_book')){$q=$pdo->prepare('SELECT a.scheduled_at,a.status,a.reason,u.full_name AS doctor_name FROM appointments a LEFT JOIN doctors d ON d.id=a.doctor_id LEFT JOIN users u ON u.id=d.user_id WHERE a.patient_id=:patient ORDER BY a.scheduled_at DESC LIMIT 50');$q->execute(['patient'=>$patient['id']]);$appointments=$q->fetchAll();}
$prescriptions=[];if(has_permission('prescriptions.own_view')){$q=$pdo->prepare('SELECT p.created_at,m.name,m.unit,pi.dosage,pi.quantity,pi.instructions,pd.dispensed_at FROM prescriptions p JOIN prescription_items pi ON pi.prescription_id=p.id JOIN medicines m ON m.id=pi.medicine_id LEFT JOIN prescription_dispensations pd ON pd.prescription_item_id=pi.id WHERE p.patient_id=:patient ORDER BY p.created_at DESC LIMIT 100');$q->execute(['patient'=>$patient['id']]);$prescriptions=$q->fetchAll();}
$labResults=[];if(has_permission('lab.results.own_view')){$q=$pdo->prepare('SELECT t.test_name,t.requested_at,r.result,r.recorded_at FROM lab_tests t JOIN lab_results r ON r.lab_test_id=t.id WHERE t.patient_id=:patient AND t.status=\'completed\' ORDER BY r.recorded_at DESC LIMIT 100');$q->execute(['patient'=>$patient['id']]);$labResults=$q->fetchAll();}
$radiology=[];if(has_permission('radiology.results.own_view')){$q=$pdo->prepare('SELECT scan_name,report,completed_at FROM radiology_requests WHERE patient_id=:patient AND status=\'completed\' ORDER BY completed_at DESC LIMIT 100');$q->execute(['patient'=>$patient['id']]);$radiology=$q->fetchAll();}
$invoices=[];if(has_permission('invoices.own_view')){$q=$pdo->prepare('SELECT i.invoice_no,i.total_amount,i.status,i.created_at,COALESCE(SUM(pay.amount),0) AS paid FROM invoices i LEFT JOIN payments pay ON pay.invoice_id=i.id WHERE i.patient_id=:patient GROUP BY i.id ORDER BY i.created_at DESC LIMIT 50');$q->execute(['patient'=>$patient['id']]);$invoices=$q->fetchAll();}
$pageTitle='My patient portal';require __DIR__.'/../includes/header.php';?>
<div class="page-heading"><div><h2>Welcome, <?=e($patient['first_name'])?></h2><p>Your portal is linked to patient number <?=e($patient['patient_no'])?>. Only your records appear here.</p></div></div>
<?php if(has_permission('appointments.self_book')):?><section class="content-card form-card mt-0"><div class="card-heading"><h3>Request an appointment</h3></div><form method="post" class="row g-3"><?=csrf_field()?><input type="hidden" name="action" value="book"><div class="col-md-3"><label class="form-label">Clinician</label><select class="form-select" name="doctor_id" required><option value="">Select clinician</option><?php foreach($doctors as $d):?><option value="<?=(int)$d['id']?>"><?=e($d['full_name'])?></option><?php endforeach;?></select></div><div class="col-md-3"><label class="form-label">Preferred date and time</label><input class="form-control" type="datetime-local" name="scheduled_at" min="<?=e(date('Y-m-d\TH:i'))?>" required></div><div class="col-md-3"><label class="form-label">Reason</label><input class="form-control" name="reason" maxlength="255"></div><div class="col-md-3 d-flex align-items-end"><button class="btn btn-primary">Request</button></div></form><div class="form-text mt-2">Requests are subject to confirmation by the hospital.</div></section><?php endif;?>
<?php if(has_permission('appointments.self_book')): ?><section class="content-card"><div class="card-heading"><h3>My appointments</h3></div><div class="table-responsive"><table class="table"><thead><tr><th>Date</th><th>Clinician</th><th>Reason</th><th>Status</th></tr></thead><tbody><?php if(!$appointments):?><tr><td colspan="4" class="empty-state">No appointments yet.</td></tr><?php else:foreach($appointments as $a):?><tr><td><?=e(date('M j, Y g:i a',strtotime($a['scheduled_at'])))?></td><td><?=e($a['doctor_name']??'To be assigned')?></td><td><?=e($a['reason']?:'—')?></td><td><?=e(ucwords(str_replace('_',' ',$a['status'])))?></td></tr><?php endforeach;endif;?></tbody></table></div></section><?php endif; ?>
<?php if(has_permission('prescriptions.own_view')): ?><section class="content-card"><div class="card-heading"><h3>My prescriptions</h3></div><div class="table-responsive"><table class="table"><thead><tr><th>Date</th><th>Medicine</th><th>Directions</th><th>Dispensing</th></tr></thead><tbody><?php if(!$prescriptions):?><tr><td colspan="4" class="empty-state">No prescriptions available.</td></tr><?php else:foreach($prescriptions as $p):?><tr><td><?=e(date('M j, Y',strtotime($p['created_at'])))?></td><td><?=e($p['name'])?></td><td><?=e($p['dosage'].' · '.$p['quantity'].' '.$p['unit'].($p['instructions']?' · '.$p['instructions']:''))?></td><td><?=$p['dispensed_at']?'Dispensed '.e(date('M j, Y',strtotime($p['dispensed_at']))):'Awaiting dispensing'?></td></tr><?php endforeach;endif;?></tbody></table></div></section><?php endif; ?>
<?php if(has_permission('lab.results.own_view')||has_permission('radiology.results.own_view')): ?><section class="content-card"><div class="card-heading"><h3>My test results</h3></div><div class="table-responsive"><table class="table"><thead><tr><th>Test</th><th>Recorded</th><th>Result</th></tr></thead><tbody><?php if(!$labResults):?><tr><td colspan="3" class="empty-state">No completed laboratory results available.</td></tr><?php else:foreach($labResults as $r):?><tr><td><?=e($r['test_name'])?></td><td><?=e(date('M j, Y',strtotime($r['recorded_at'])))?></td><td><?=nl2br(e($r['result']))?></td></tr><?php endforeach;endif;?></tbody></table></div><?php if($radiology):?><div class="card-heading"><h4>Imaging reports</h4></div><div class="p-3"><?php foreach($radiology as $r):?><details class="mb-2"><summary><?=e($r['scan_name'].' · '.date('M j, Y',strtotime($r['completed_at'])))?></summary><?=nl2br(e($r['report']))?></details><?php endforeach;?></div><?php endif;?></section><?php endif; ?>
<?php if(has_permission('invoices.own_view')): ?><section class="content-card"><div class="card-heading"><h3>My invoices</h3></div><div class="table-responsive"><table class="table"><thead><tr><th>Invoice</th><th>Date</th><th>Total</th><th>Paid</th><th>Status</th></tr></thead><tbody><?php if(!$invoices):?><tr><td colspan="5" class="empty-state">No invoices available.</td></tr><?php else:foreach($invoices as $i):?><tr><td><?=e($i['invoice_no'])?></td><td><?=e(date('M j, Y',strtotime($i['created_at'])))?></td><td><?=number_format((float)$i['total_amount'],2)?></td><td><?=number_format((float)$i['paid'],2)?></td><td><?=e(ucfirst($i['status']))?></td></tr><?php endforeach;endif;?></tbody></table></div></section><?php endif; ?>
<?php if(has_permission('profile.own_update')):?><section class="content-card"><div class="card-heading"><h3>Update contact details</h3></div><form method="post" class="row g-3 p-3"><?=csrf_field()?><input type="hidden" name="action" value="profile"><div class="col-md-4"><label class="form-label">Phone</label><input class="form-control" name="phone" maxlength="40" value="<?=e($patient['phone'])?>"></div><div class="col-md-4"><label class="form-label">Email</label><input class="form-control" type="email" name="email" maxlength="190" value="<?=e($patient['email'])?>"></div><div class="col-md-4"><label class="form-label">Address</label><input class="form-control" name="address" maxlength="255" value="<?=e($patient['address'])?>"></div><div class="col-12"><button class="btn btn-primary">Save profile</button></div></form></section><?php endif;?>
<?php require __DIR__.'/../includes/footer.php';?>
